class CoursesManager{constructor(){this.container=document.getElementById('course-items-container');this.totalFormsInput=document.getElementById('id_courses-TOTAL_FORMS');this.emptyState=document.getElementById('course-empty-state');this.counterEl=document.getElementById('courses-counter');if (!this.container||!this.totalFormsInput)return;this.init();}init(){this.attachAddHandler();this.attachItemHandlers();this.updateState();}attachAddHandler(){const addBtn=document.getElementById('course-add-btn');if (addBtn){addBtn.addEventListener('click',(e)=>{e.preventDefault();this.addCourse();});}}addCourse(){const totalForms=parseInt(this.totalFormsInput.value);const newIndex=totalForms;this.container.querySelectorAll('.course-item:not(.course-item--deleted)').forEach(item=>{this.toggleContent(item,false);});const item=this.createCourseItem(newIndex);this.container.appendChild(item);this.totalFormsInput.value=newIndex+1;requestAnimationFrame(()=>{item.classList.add('course-item--visible');});this.attachItemHandlers();this.updateState();this.updateSortOrders();this.toggleContent(item,true);const durationInput=item.querySelector('input[name$="-duration"]');if (durationInput){setTimeout(()=>durationInput.focus(),150);}}importCourse(course){this.addCourse();const allItems=this.container.querySelectorAll('.course-item');const newCourseItem=allItems[allItems.length-1];const durationInput=newCourseItem.querySelector('input[name$="-duration"]');const myrInput=newCourseItem.querySelector('input[name$="-fees_myr"]');const usdInput=newCourseItem.querySelector('input[name$="-fees_usd"]');const sarInput=newCourseItem.querySelector('input[name$="-fees_sar"]');const visaInput=newCourseItem.querySelector('input[name$="-visa_duration"]');if (durationInput){durationInput.value=course.duration||'';this.updatePreview(newCourseItem);}if (myrInput){myrInput.value=course.fees_myr||'';}if (usdInput){usdInput.value=course.fees_usd||'';}if (sarInput){sarInput.value=course.fees_sar||'';}if (visaInput){visaInput.value=course.visa_duration||'';}}createCourseItem(index){const item=document.createElement('div');item.className='course-item';item.setAttribute('data-course-index',index);item.innerHTML=`<div class="course-item__header"><span class="course-item__drag-handle" title="اسحب لإعادة الترتيب"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="6" r="1.5"/><circle cx="15" cy="6" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="18" r="1.5"/><circle cx="15" cy="18" r="1.5"/></svg></span><div class="course-item__number">${index+1}</div><span class="course-item__title-preview">صف رسوم جديد</span><button type="button" class="course-item__toggle" title="عرض/إخفاء الحقول" data-toggle-content><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"></polyline></svg></button><button type="button" class="course-item__delete" title="حذف"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a2 2 0 012-2h4a2 2 0 012 2v2m3 0v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6h14"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg></button></div><div class="course-item__content"><div class="course-grid"><div class="course-item__field"><label for="id_courses-${index}-duration">مدة الكورس</label><input type="text" name="courses-${index}-duration" id="id_courses-${index}-duration" class="course-duration-input w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" placeholder="مثال:شهر، شهرين" required dir="rtl"></div><div class="course-item__field"><label for="id_courses-${index}-fees_myr">الرسوم(MYR)</label><input type="text" name="courses-${index}-fees_myr" id="id_courses-${index}-fees_myr" class="course-fees-myr-input w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" placeholder="مثال:3,400" required dir="rtl"></div><div class="course-item__field"><label for="id_courses-${index}-fees_usd">الرسوم(USD)</label><input type="text" name="courses-${index}-fees_usd" id="id_courses-${index}-fees_usd" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" placeholder="مثال:857" dir="rtl"></div><div class="course-item__field"><label for="id_courses-${index}-fees_sar">الرسوم(SAR)</label><input type="text" name="courses-${index}-fees_sar" id="id_courses-${index}-fees_sar" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" placeholder="مثال:3,216" dir="rtl"></div><div class="course-item__field"><label for="id_courses-${index}-visa_duration">تأشيرة الطالب</label><input type="text" name="courses-${index}-visa_duration" id="id_courses-${index}-visa_duration" class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" placeholder="مثال:بدون تأشيرة" dir="rtl"></div></div><input type="hidden" name="courses-${index}-sort_order" value="${index}"><input type="hidden" name="courses-${index}-id" value=""><input type="hidden" name="courses-${index}-DELETE" value=""></div>`;return item;}deleteItem(item){const deleteInput=item.querySelector('input[name$="-DELETE"]');const idInput=item.querySelector('input[name$="-id"]');if (idInput&&idInput.value){deleteInput.value='on';item.classList.add('course-item--deleted');setTimeout(()=>{item.style.display='none';this.updateState();this.updateNumbers();},300);}else{item.classList.add('course-item--deleted');setTimeout(()=>{item.remove();this.reindexForms();this.updateState();},300);}}toggleContent(item,forceExpand=null){const content=item.querySelector('.course-item__content');const toggleBtn=item.querySelector('[data-toggle-content]');const icon=toggleBtn.querySelector('svg');const isExpanded=content.classList.contains('expanded');const shouldExpand=forceExpand!==null?forceExpand:!isExpanded;if (shouldExpand){content.classList.add('expanded');icon.classList.add('rotated');toggleBtn.setAttribute('aria-expanded','true');}else{content.classList.remove('expanded');icon.classList.remove('rotated');toggleBtn.setAttribute('aria-expanded','false');}}updatePreview(item){const durationInput=item.querySelector('input[name$="-duration"]');const feesMyrInput=item.querySelector('input[name$="-fees_myr"]');const preview=item.querySelector('.course-item__title-preview');if (preview){const duration=durationInput?durationInput.value.trim():'';const feesMyr=feesMyrInput?feesMyrInput.value.trim():'';if (duration||feesMyr){preview.textContent=`مدة الكورس:${duration||'—'}|الرسوم الدراسية:${feesMyr?(feesMyr+' MYR'):'—'}`;}else{preview.textContent='صف رسوم جديد';}}}reindexForms(){const allItems=this.container.querySelectorAll('.course-item');allItems.forEach((item,idx)=>{item.setAttribute('data-course-index',idx);const inputs=item.querySelectorAll('input,textarea,select');inputs.forEach(input=>{const name=input.getAttribute('name');if (name){input.setAttribute('name',name.replace(/courses-\d+-/,`courses-${idx}-`));}const id=input.getAttribute('id');if (id){input.setAttribute('id',id.replace(/id_courses-\d+-/,`id_courses-${idx}-`));}});const labels=item.querySelectorAll('label');labels.forEach(label=>{const htmlFor=label.getAttribute('for');if (htmlFor){label.setAttribute('for',htmlFor.replace(/id_courses-\d+-/,`id_courses-${idx}-`));}});});this.totalFormsInput.value=allItems.length;this.updateNumbers();}updateNumbers(){const visibleItems=this.container.querySelectorAll('.course-item:not(.course-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const numberEl=item.querySelector('.course-item__number');if (numberEl)numberEl.textContent=idx+1;});}updateSortOrders(){const visibleItems=this.container.querySelectorAll('.course-item:not(.course-item--deleted):not([style*="display:none"])');visibleItems.forEach((item,idx)=>{const sortInput=item.querySelector('input[name$="-sort_order"]');if (sortInput)sortInput.value=idx;});}updateState(){const visibleItems=this.container.querySelectorAll('.course-item:not(.course-item--deleted):not([style*="display:none"])');const count=visibleItems.length;if (this.emptyState){this.emptyState.style.display=count===0?'flex':'none';}if (this.counterEl){this.counterEl.textContent=count;this.counterEl.style.display=count>0?'inline-flex':'none';}}attachItemHandlers(){this.container.querySelectorAll('.course-item__delete').forEach(btn=>{btn.onclick=(e)=>{e.preventDefault();const item=btn.closest('.course-item');this.deleteItem(item);};});this.container.querySelectorAll('[data-toggle-content]').forEach(btn=>{btn.onclick=(e)=>{e.preventDefault();const item=btn.closest('.course-item');this.toggleContent(item);};});this.container.querySelectorAll('.course-item__header').forEach(header=>{header.onclick=(e)=>{if (e.target.closest('.course-item__delete')||e.target.closest('.course-item__toggle')||e.target.closest('.course-item__drag-handle')){return;}e.preventDefault();const item=header.closest('.course-item');this.toggleContent(item);};});this.container.querySelectorAll('input').forEach(input=>{if (input.name.includes('-duration')||input.name.includes('-fees_myr')){input.addEventListener('input',(e)=>{const item=e.target.closest('.course-item');this.updatePreview(item);});}});this.container.querySelectorAll('.course-item').forEach(item=>{item.setAttribute('draggable','true');item.ondragstart=(e)=>this.onDragStart(e,item);item.ondragend=(e)=>this.onDragEnd(e,item);item.ondragover=(e)=>this.onDragOver(e,item);item.ondrop=(e)=>this.onDrop(e,item);});this.container.querySelectorAll('.course-item').forEach(item=>{this.updatePreview(item);});}onDragStart(e,item){item.classList.add('course-item--dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','');}onDragEnd(e,item){item.classList.remove('course-item--dragging');this.container.querySelectorAll('.course-item--drag-over').forEach(el=>{el.classList.remove('course-item--drag-over');});this.updateSortOrders();this.reindexForms();}onDragOver(e,item){e.preventDefault();e.dataTransfer.dropEffect='move';this.container.querySelectorAll('.course-item--drag-over').forEach(el=>{el.classList.remove('course-item--drag-over');});if (!item.classList.contains('course-item--dragging')){item.classList.add('course-item--drag-over');}}onDrop(e,item){e.preventDefault();item.classList.remove('course-item--drag-over');const draggedItem=this.container.querySelector('.course-item--dragging');if (draggedItem&&draggedItem!==item){const allItems=[...this.container.querySelectorAll('.course-item:not([style*="display:none"])')];const draggedIdx=allItems.indexOf(draggedItem);const targetIdx=allItems.indexOf(item);if (draggedIdx<targetIdx){item.after(draggedItem);}else{item.before(draggedItem);}}}}document.addEventListener('DOMContentLoaded',()=>{window.coursesManager=new CoursesManager();});